package io.github.borderarea01.znote;

import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;

/** :capture owns durable submissions; a closing Activity never owns the POST. */
final class CaptureOutbox {
    private static final ExecutorService WORK=Executors.newSingleThreadExecutor();
    private static final Handler MAIN=new Handler(Looper.getMainLooper());
    private static boolean initialized,running;private static volatile int active;
    private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("CaptureOutbox",0);}
    static synchronized JSONArray list(Context c){try{return new JSONArray(prefs(c).getString("entries","[]"));}catch(JSONException e){throw new IllegalStateException("待提交任务无法读取，请保留应用数据");}}
    private static synchronized void save(Context c,JSONArray entries)throws IOException{if(!prefs(c).edit().putString("entries",entries.toString()).commit())throw new IOException("手机任务保存失败，请检查存储空间");active=0;for(int i=0;i<entries.length();i++)if(!"failed".equals(entries.optJSONObject(i).optString("state")))active++;}
    static int activeCount(){return active;}
    static synchronized void resume(Context source){Context c=source.getApplicationContext();if(!initialized){initialized=true;JSONArray rows=list(c);for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if("sending".equals(row.optString("state")))try{row.put("state","failed").put("error","提交被中断，结果尚未确认；重试会沿用原编号");}catch(JSONException ignored){}}try{save(c,rows);}catch(IOException e){notice(c,"恢复待提交任务失败，请检查手机存储");return;}}pump(c);}
    static synchronized void enqueue(Context source,String value,String collection,boolean note,String id)throws Exception{
        Context c=source.getApplicationContext();resume(c);if(value==null||value.length()>16000||CaptureAssistService.link(value).isEmpty())throw new IOException("请提供完整作品链接");JSONArray rows=list(c);for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).getString("id")))return;
        if(rows.length()>=16)throw new IOException("手机待提交任务已满，请在待提交任务中处理旧记录");
        CaptureCatalogue.Snapshot cache=CaptureCatalogue.read(c);rows.put(new JSONObject().put("id",id).put("text",value).put("collection",collection==null?"":collection).put("note",note).put("profile",cache.profile).put("origin","").put("state","pending").put("error","").put("created_at",System.currentTimeMillis()));save(c,rows);pump(c);
    }
    static synchronized void retry(Context c,String id)throws Exception{JSONArray rows=list(c);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(id.equals(row.getString("id"))&&"failed".equals(row.getString("state"))){row.put("state",row.has("job")?"accepted":"pending").put("error","");save(c,rows);pump(c);return;}}}
    static synchronized void remove(Context c,String id)throws Exception{JSONArray rows=list(c),next=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(id.equals(row.getString("id"))){if(!"failed".equals(row.getString("state")))throw new IOException("提交中的任务请等待结果");}else next.put(row);}save(c,next);}
    private static synchronized void update(Context c,JSONObject row,boolean remove)throws Exception{JSONArray rows=list(c),next=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject old=rows.getJSONObject(i);if(old.getString("id").equals(row.getString("id"))){if(!remove)next.put(row);}else next.put(old);}save(c,next);}
    private static synchronized void pump(Context c){if(running)return;running=true;WORK.execute(()->{try{while(true){JSONObject row=null;synchronized(CaptureOutbox.class){JSONArray rows=list(c);for(int i=0;i<rows.length();i++){JSONObject candidate=rows.getJSONObject(i);if("pending".equals(candidate.optString("state"))||CaptureAssistService.current!=null&&"accepted".equals(candidate.optString("state"))){row=candidate;break;}}if(row==null)return;}submit(c,row);}}catch(Exception e){notice(c,"手机待提交任务暂时无法处理，请打开待提交任务查看");}finally{synchronized(CaptureOutbox.class){running=false;try{JSONArray rows=list(c);for(int i=0;i<rows.length();i++)if("pending".equals(rows.getJSONObject(i).optString("state"))){pump(c);break;}}catch(Exception ignored){}}}});}
    private static void submit(Context c,JSONObject row){HttpURLConnection connection=null;try{
        if(!"accepted".equals(row.optString("state"))){
            row.put("state","sending");update(c,row,false);String pinned=row.optString("origin");Bundle session=c.getContentResolver().call(Uri.parse("content://"+c.getPackageName()+".capture-session"),"session",pinned.isEmpty()?null:pinned,null);
            if(session==null||session.getString("origin","").isEmpty())throw new IOException("请打开 ZNote 配置连接并登录；任务已保留");
            String profile=row.optString("profile");if(!profile.isEmpty()&&!profile.equals(session.getString("profile","")))throw new IOException("服务器连接已变更，请处理原任务后重新采集；链接已保留");
            CaptureCatalogue.validate(c,session,row.getString("collection"));String origin=MainActivity.normalize(session.getString("origin"));row.put("origin",origin).put("profile",session.getString("profile",""));update(c,row,false);
            JSONObject input=new JSONObject().put("text",row.getString("text")).put("collection_id",row.getString("collection").isEmpty()?JSONObject.NULL:row.getString("collection")).put("image_mode",row.getBoolean("note")?"note":"group").put("request_id","android:"+row.getString("id"));
            String url=CaptureAssistService.link(row.getString("text"));if(!PixivSession.work(url).isEmpty()){Bundle resolved=c.getContentResolver().call(Uri.parse("content://"+c.getPackageName()+".capture-session"),"pixiv",url,null);if(resolved==null||resolved.getBoolean("requires_login",false))throw new IOException("需要手机 Pixiv 登录，请打开待提交任务处理");if(!resolved.getString("error","").isEmpty())throw new IOException(resolved.getString("error"));input.put("browser_pixiv",new JSONObject(resolved.getString("post","{}")));}
            connection=(HttpURLConnection)(ConnectionRoutes.local(origin)?new URL(origin+"/api/captures").openConnection(Proxy.NO_PROXY):new URL(origin+"/api/captures").openConnection());connection.setConnectTimeout(8000);connection.setReadTimeout(15000);connection.setInstanceFollowRedirects(false);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json; charset=utf-8");String token=session.getString("token",""),cookie=session.getString("cookie","");if(!token.isEmpty())connection.setRequestProperty("Authorization","Bearer "+token);else if(!cookie.isEmpty())connection.setRequestProperty("Cookie",cookie);
            // Streaming prevents HttpURLConnection from silently replaying a buffered POST.
            byte[] payload=input.toString().getBytes(StandardCharsets.UTF_8);connection.setFixedLengthStreamingMode(payload.length);try(OutputStream out=connection.getOutputStream()){out.write(payload);}int code=connection.getResponseCode();ByteArrayOutputStream data=new ByteArrayOutputStream();InputStream response=code>=400?connection.getErrorStream():connection.getInputStream();if(response!=null)try(InputStream in=response){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(data.size()+n>1024*1024)throw new IOException("服务器响应过大，任务已保留");data.write(b,0,n);}}
            JSONObject result;try{result=new JSONObject(data.toString("UTF-8"));}catch(JSONException e){throw new IOException("提交结果尚未确认，请在待提交任务中重试");}if(code<200||code>=300)throw new IOException(result.optString("error",code==401?"授权已失效，请打开 ZNote 登录后重试":"提交失败（HTTP "+code+"）"));row.put("job",result.getString("id")).put("state","accepted");update(c,row,false);
        }
        final JSONObject accepted=row;CompletableFuture<Boolean> handed=new CompletableFuture<>();MAIN.post(()->{try{CaptureAssistService service=CaptureAssistService.current;if(service!=null){service.backgroundQueued(accepted.optString("job"),accepted.optString("origin"));handed.complete(true);}else handed.complete(false);}catch(Exception e){handed.completeExceptionally(e);}});if(handed.get(5,TimeUnit.SECONDS))update(c,row,true);else notice(c,"服务器已接收任务，可在知识库最近下载查看结果");
    }catch(Exception e){try{row.put("state","failed").put("error",e.getMessage()==null?"提交未完成，任务已保留":e.getMessage());update(c,row,false);}catch(Exception ignored){}notice(c,"提交未完成，链接和选库已保留；点击查看待提交任务");}finally{if(connection!=null)connection.disconnect();}}
    static void notice(Context c,String message){MAIN.post(()->{CaptureAssistService service=CaptureAssistService.current;if(service!=null)service.pendingSubmitNotice(message);NotificationManager manager=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("capture_submissions","手机提交结果",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,3800,new Intent(c,CapturePendingActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);try{manager.notify(3800,new Notification.Builder(c,"capture_submissions").setSmallIcon(R.drawable.ic_capture_notification).setContentTitle("ZNote 待提交任务").setContentText(message).setContentIntent(open).setAutoCancel(true).build());}catch(SecurityException ignored){}});}
}
